import os,sys
exec(open('/home/user/workspace/build_base_v4.py').read().split("PAGES=")[0])  # live, LANGS
OUT='/home/user/workspace/jager'
GH='https://github.com/paulfxyz'
GHI='<img src="{b}assets/icons/github.svg" alt="" width="20" height="20">'
def w(n,h):
    p=os.path.join(OUT,n); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,'w').write(h)

def build(L):
    fr=(L=='fr'); b='../' if fr else ''
    t=lambda en,f: f if fr else en
    ghi=GHI.format(b=b)
    def chatbox(id,auto=False,interactive=False,ch='whatsapp',tabs=False):
        tb=''
        if tabs: tb='<div class="c-tabs" role="tablist" aria-label="Channel">'+''.join(f'<button type="button" role="tab" data-ch="{k}" aria-selected="{str(ch==k).lower()}">{n}</button>' for k,n in [('whatsapp','WhatsApp'),('telegram','Telegram')])+'</div>'
        ph=t('Message Jager…','Écris à Jager…')
        form=(f'<form class="c-form" autocomplete="off"><label class="sr" for="{id}In">{ph}</label><input id="{id}In" type="text" maxlength="160" placeholder="{ph}"><button type="submit" aria-label="Send">➤</button></form>') if interactive else ''
        return f'<div class="chat" id="{id}" data-ch="{ch}" data-auto="{1 if auto else 0}"><div class="c-top"><span class="av">J</span><div class="c-who"><b>Jager</b><small class="c-sub">{t("online · probably judging you","en ligne · te juge probablement")}</small></div>{tb}</div><div class="c-body" aria-live="polite"></div>{form}</div>'
    TABS='<div class="c-tabs" role="tablist" aria-label="Channel"><button type="button" role="tab" data-ch="whatsapp" aria-selected="true">WhatsApp</button><button type="button" role="tab" data-ch="telegram" aria-selected="false">Telegram</button></div>'
    def head(title,desc,page,body='on-dark'):
        alt_en=f'https://jager.social/{"" if page=="index.html" else page}'; alt_fr=f'https://jager.social/fr/{"" if page=="index.html" else page}'
        can=alt_fr if fr else alt_en
        return f'''<!doctype html><html lang="{L}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><meta name="description" content="{desc}"><meta name="theme-color" content="#07061a">
<link rel="canonical" href="{can}"><link rel="alternate" hreflang="en" href="{alt_en}"><link rel="alternate" hreflang="fr" href="{alt_fr}"><link rel="alternate" hreflang="x-default" href="{alt_en}"><link rel="icon" href="{b}favicon.svg" type="image/svg+xml">
<meta property="og:type" content="website"><meta property="og:site_name" content="Jager"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:image" content="https://jager.social/og.png"><meta name="twitter:card" content="summary_large_image">
<link rel="preload" href="{b}assets/fonts/BricolageGrotesque-800-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="{b}fonts.css"><link rel="stylesheet" href="{b}night.css"></head>
<body class="{body}"><script>document.documentElement.classList.add('js');try{{if(document.cookie.indexOf('jagerDrunk=off')>-1)document.documentElement.classList.add('no-drunk')}}catch(e){{}}</script><div class="prog" id="prog"></div>
<div class="hud" aria-hidden="true"><div class="orb" id="orb"></div><div class="clock" id="clock">21:00</div></div>
'''
    def langlist(page):
        out=''
        for l in LANGS:
            if l=='English': out+=f'<li><a href="{"../" if fr else ""}{page}" hreflang="en"{" aria-current=\"true\"" if not fr else ""}>English</a></li>'
            elif l=='Français': out+=f'<li><a href="{"" if fr else "fr/"}{page}" hreflang="fr"{" aria-current=\"true\"" if fr else ""}>Français</a></li>'
        out+=f'<li class="sep mono">{t("Translations welcome","Traductions bienvenues")}</li>'
        out+=''.join(f'<li><button type="button" class="dis" data-lang="{l}">{l}</button></li>' for l in LANGS if l not in ('English','Français'))
        return out
    def nav(page,active=''):
        items=[("index.html#what",t("What is it","C'est quoi")),("index.html#night",t("The night","La nuit")),("index.html#try",t("Try it","Essayer")),("setup.html",t("Setup","Installation")),("index.html#faq","FAQ")]
        links=''.join(f'<li><a href="{h}"{" aria-current=\"page\"" if h==active else ""}>{x}</a></li>' for h,x in items)
        return f'''<header class="nav" id="nav"><div class="wrap in"><a class="logo" href="index.html" aria-label="Jager">jager<i>.</i></a>
<ul id="menu">{links}<li class="only-m"><a href="{GH}" rel="noopener">GitHub</a></li></ul>
<div class="lang"><button class="lang-btn" id="langBtn" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="Language">🌐 <span>{L.upper()}</span></button><ul class="lang-list" id="langList" hidden>{langlist(page)}</ul></div>
<span class="mit mono">MIT</span><a class="btn" href="{GH}" rel="noopener">{ghi} GitHub</a>
<button class="burger" id="burger" type="button" aria-label="Menu" aria-expanded="false"><span></span><span></span></button></div></header>'''
    FOOT=f'''<footer class="foot"><div class="wrap">
<div class="sf-pitch"><div><span class="sf-pill mono"><b></b> {t("Free · open source · MIT","Gratuit · open source · MIT")}</span>
<h2 class="sf-title">{t("Last call.<br><span class='serif'>Clean timeline.</span>","Dernier verre.<br><span class='serif'>Timeline propre.</span>")}</h2>
<p class="sf-sub">{t("Jager is a free, MIT-licensed buddy for your public comments and posts. Bring a Zernio key. Chat on WhatsApp or Telegram.","Jager est un buddy gratuit sous licence MIT pour tes commentaires et publications publics. Apporte une clé Zernio. Discute sur WhatsApp ou Telegram.")}</p>
<div class="sf-cta"><a class="btn btn--pink btn--lg" href="{GH}" rel="noopener">{ghi} {t("View on GitHub","Voir sur GitHub")} →</a><a class="sf-ask" href="mailto:ask@jager.social">ask@jager.social</a></div></div>
<nav class="sf-cols" aria-label="Footer">
<div><h4 class="mono">{t("Project","Projet")}</h4><a href="index.html#what">{t("What is it","C'est quoi")}</a><a href="index.html#night">{t("The night","La nuit")}</a><a href="index.html#try">{t("Try it","Essayer")}</a><a href="setup.html">{t("Setup guide","Guide d'installation")}</a><a href="index.html#faq">FAQ</a></div>
<div><h4 class="mono">{t("Built on","Construit avec")}</h4><a href="https://zernio.com" rel="noopener">Zernio</a><a href="https://openrouter.ai" rel="noopener">OpenRouter</a><a href="https://runware.ai" rel="noopener">Runware</a></div>
<div><h4 class="mono">Open source</h4><a href="{GH}" rel="noopener">GitHub</a><a href="setup.html#license">{t("MIT license","Licence MIT")}</a><a href="setup.html#contribute">{t("Contribute","Contribuer")}</a></div>
<div><h4 class="mono">{t("Say hello","Dis bonjour")}</h4><a href="mailto:ask@jager.social">Contact</a><button type="button" id="footLang">{t("Languages","Langues")}</button><a href="https://iris.online" rel="noopener">Iris</a><a href="https://digital.spot" rel="noopener">Digital Spot</a></div></nav></div>
<div class="sf-word" aria-hidden="true">Jager</div>
<div class="sf-legal"><a class="logo" href="index.html">jager<i>.</i></a>
<ul class="sf-facts"><li>© 2026 Enki Ltd. {t("Released under the MIT License","Publié sous licence MIT")}</li><li>{t("Company number","N° d'entreprise")} 2067348138</li><li>14 Antim I Street, fl. 1 &amp; 2, Sofia, Bulgaria</li><li><a href="mailto:ask@jager.social">ask@jager.social</a></li><li><button type="button" class="dtoggle mono" id="drunkToggle" aria-pressed="true">{t("Drunk mode","Mode ivre")}: <b>ON</b></button></li></ul>
<p class="sf-note">{t("Jager is a sister project of","Jager est un projet frère de")} <a href="https://iris.online" rel="noopener">Iris</a> {t("and","et")} <a href="https://digital.spot" rel="noopener">Digital Spot</a>{t(", which are made by Enki Ltd. The software is provided as is, without warrantyBrand names and logos belong to their owners; no endorsement is implied. Not affiliated with Jägermeister, Zernio, WhatsApp, Telegram or Meta. Please drink and post responsibly.", ", réalisés par Enki Ltd. Le logiciel est fourni tel quel, sans garantie. Les marques et logos appartiennent à leurs propriétaires ; aucune approbation n'est sous-entendue. Non affilié à Jägermeister, Zernio, WhatsApp, Telegram ou Meta. Bois et publie avec modération.").replace('warrantyBrand','warranty. Brand')}</p></div>
</div></footer><div class="toast" id="toast" role="status" aria-live="polite"></div>
<script src="{b}chat.js" defer></script><script src="{b}night.js" defer></script></body></html>'''
    ROT='|'.join(t("texting your ex|quote-tweeting your boss|rating a kebab shop one star|commenting “marry me” on a stranger's dog|a LinkedIn post about synergy at 3 AM","écrire à ton ex|citer ton boss en public|mettre une étoile à un kebab|commenter « épouse-moi » sous le chien d'un inconnu|un post LinkedIn sur la synergie à 3 h du mat").split('|') if False else (["texting your ex","quote-tweeting your boss","rating a kebab shop one star","commenting “marry me” on a stranger's dog","a LinkedIn post about synergy at 3 AM"] if not fr else ["écrire à ton ex","citer ton boss en public","mettre une étoile à un kebab","commenter « épouse-moi » sous le chien d'un inconnu","un post LinkedIn sur la synergie à 3 h du mat"]))
    tickw=t(["Free","MIT licensed","Bring your own keys","WhatsApp","Telegram","Weekly sprints","No signup","Open source"],["Gratuit","Licence MIT","Tes propres clés","WhatsApp","Telegram","Sprints hebdo","Sans inscription","Open source"])
    tick='<div class="tick" aria-hidden="true"><div class="tr">'+('<div>'+''.join(f'<span>{x}</span>' for x in tickw)+'</div>')*4+'</div></div>'
    PL=[("x","X",t("The 2 AM hot take.","Le hot take de 2 h du mat.")),("instagram","Instagram",t("The story you regret, and the comments under it.","La story que tu regrettes et ses commentaires.")),("facebook","Facebook",t("Old posts your uncle still reacts to.","Les vieux posts que ton oncle commente encore.")),("linkedin","LinkedIn",t("Synergy posts and awkward replies.","Les posts synergie et les réponses gênantes.")),("tiktok","TikTok",t("Videos and the comment section.","Les vidéos et leurs commentaires.")),("youtube","YouTube",t("Comments on your videos, trolls included.","Les commentaires sous tes vidéos, trolls inclus.")),("threads","Threads",t("Casual posts that were not casual.","Des posts décontractés qui ne l'étaient pas.")),("bluesky","Bluesky",t("Posts and replies in the open.","Posts et réponses en public.")),("pinterest","Pinterest",t("Pins and boards you forgot about.","Des épingles et tableaux oubliés.")),("reddit","Reddit",t("Posts and comments with your name on them.","Posts et commentaires à ton nom.")),("googlemaps","Google Business",t("Reviews and replies for your place.","Avis et réponses pour ton établissement.")),("snapchat","Snapchat",t("Public stories that outlive the night.","Des stories publiques qui survivent à la nuit."))]
    logos=''.join(f'<span class="lg"><img src="{b}assets/icons/{k}.svg" alt="{n}"></span>' for k,n,_,_ in live)
    def chap(n,ti,hh,p,m): return f'<article class="chap" data-n="{n}"><div class="hh">{hh}</div><h3>{ti}</h3><p class="drunk">{p}</p><details class="more"><summary>{t("More details","Plus de détails")}</summary><p>{m}</p></details><button class="replay mono" type="button">↻ {t("replay","rejouer")}</button></article>'
    chaps=''.join([
    chap(1,t('Plug in the keys','Branche les clés'),'21:00',t('Paste a Zernio key and an AI key. Your accounts and your WhatsApp number or Telegram bot come with them. Jager says hi.','Colle une clé Zernio et une clé IA. Tes comptes et ton numéro WhatsApp ou ton bot Telegram viennent avec. Jager te dit bonjour.'),t('Zernio holds the connections to each platform. OpenRouter is the brain. Runware is optional, for image jobs. Jager never sees a password.','Zernio gère les connexions à chaque plateforme. OpenRouter est le cerveau. Runware est optionnel, pour les images. Jager ne voit jamais un mot de passe.')),
    chap(2,t('Start a night sprint','Lance un sprint de nuit'),'23:30',t('Heading out? Say "delete everything I post in the next 10 hours, 1 hour after". That is the whole setup.','Tu sors ? Dis « supprime tout ce que je publie dans les 10 prochaines heures, 1 heure après ». C\'est toute la configuration.'),t('Say "stop" and the sprint ends at once. Hours or days, you choose.','Dis « stop » et le sprint s\'arrête aussitôt. En heures ou en jours, comme tu veux.')),
    chap(3,t('Go be a menace','Fais le fou'),'02:00',t('You post. Each post gets a timer and disappears when it runs out. Jager stays quiet, no 3 AM buzzing.','Tu publies. Chaque publication reçoit un minuteur et disparaît à la fin. Jager reste discret, aucune notification à 3 h du matin.'),t('Like your own post to keep it. Where a platform does not let apps delete posts, Jager clears comments and replies and tells you what it could not remove.','Aime ta propre publication pour la garder. Quand une plateforme n\'autorise pas la suppression par une appli, Jager nettoie les commentaires et réponses et te dit ce qu\'il n\'a pas pu retirer.')),
    chap(4,t('Clear the comments','Vide les commentaires'),'03:30',t('Start a comment sprint. Jager serves public comments one by one with a draft reply. Answer with a word.','Lance un sprint commentaires. Jager te sert les commentaires publics un par un avec un brouillon de réponse. Réponds en un mot.'),t('Replies are drafted by the AI model you picked and are never sent without your OK.','Les réponses sont rédigées par le modèle IA que tu as choisi et ne partent jamais sans ton accord.')),
    chap(5,t('The morning after','Le lendemain'),'09:00',t('Once a week, Jager lists what you posted and what people said. Reply "delete 1 3", say YES, done.','Une fois par semaine, Jager liste ce que tu as publié et ce que les gens ont dit. Réponds « supprime 1 3 », dis OUI, c\'est fait.'),t('Reminders never delete anything on their own and big deletes always ask first.','Les rappels ne suppriment jamais rien tout seuls et les grosses suppressions demandent toujours confirmation.'))])
    faq=[(t("Can I use Jager inside my own stack?","Puis-je utiliser Jager dans ma propre stack ?"),t("Yes. Run it with Docker, import it as a Python library, or give the Markdown build prompt to your own agents so they build a version that fits your setup. All of it is MIT.","Oui. Lance-le avec Docker, importe-le comme bibliothèque Python, ou donne le prompt de construction Markdown à tes propres agents pour qu'ils bâtissent une version adaptée à ton installation. Le tout est sous licence MIT.")),(t("Is Jager really free?","Jager est-il vraiment gratuit ?"),t("Yes. It is open source under the MIT license. You only pay the providers whose keys you bring, such as Zernio and your AI provider.","Oui. Il est open source sous licence MIT. Tu ne paies que les fournisseurs dont tu apportes les clés, comme Zernio et ton fournisseur d'IA.")),
    (t("Why January 1st?","Pourquoi le 1er janvier ?"),t("Because the morning after New Year's Eve is the most regrettable morning of the year. Everyone posted something at midnight. We are launching on Product Hunt that day, on purpose.","Parce que le lendemain du réveillon est le matin le plus regrettable de l'année. Tout le monde a publié quelque chose à minuit. On lance sur Product Hunt ce jour-là, exprès.")),
    (t("Why a chat and not an app or a dashboard?","Pourquoi un chat plutôt qu'une appli ou un tableau de bord ?"),t("Dashboards are for sober people with time. A chat is already open on your phone. Jager comes to you, asks one question and waits for a one-word answer.","Les tableaux de bord sont pour les gens sobres qui ont le temps. Un chat est déjà ouvert sur ton téléphone. Jager vient à toi, pose une question et attend une réponse en un mot.")),
    (t("Do I need an account with you?","Ai-je besoin d'un compte chez vous ?"),t("No. There is nothing to sign up for. You run Jager yourself and nothing passes through our servers.","Non. Il n'y a rien à créer. Tu fais tourner Jager toi-même et rien ne passe par nos serveurs.")),
    (t("What do I need to run it?","Qu'est-ce qu'il me faut pour le faire tourner ?"),t("A Zernio API key with your channels connected, an OpenRouter key (or Runware for image jobs), and any machine that can stay on: a laptop, a small server or a Raspberry Pi.","Une clé API Zernio avec tes canaux connectés, une clé OpenRouter (ou Runware pour les images), et une machine qui reste allumée : un portable, un petit serveur ou un Raspberry Pi.")),
    (t("What is a sprint?","C'est quoi un sprint ?"),t("A time-boxed job you start with a sentence. A night sprint deletes what you post after a delay. A comment sprint clears your inbox with draft replies. A launch sprint watches a post for a couple of days. A cleanup sprint reviews old posts.","Une tâche limitée dans le temps que tu lances en une phrase. Un sprint de nuit supprime ce que tu publies après un délai. Un sprint commentaires vide ta boîte avec des brouillons de réponse. Un sprint lancement surveille une publication pendant quelques jours. Un sprint ménage passe en revue les anciennes publications.")),
    (t("Will Jager delete things without asking?","Jager supprime-t-il des choses sans demander ?"),t("Only inside a sprint you started. Weekly reminders never delete anything on their own and big deletes always ask first.","Seulement dans un sprint que tu as lancé. Les rappels hebdo ne suppriment jamais rien tout seuls et les grosses suppressions demandent toujours confirmation.")),
    (t("Can Jager delete every post on every platform?","Jager peut-il tout supprimer sur toutes les plateformes ?"),t("It can do what each platform's API allows. On some platforms, such as Instagram and TikTok, apps can only manage comments and replies. Jager tells you what it could and could not remove.","Il fait ce que l'API de chaque plateforme permet. Sur certaines, comme Instagram et TikTok, les applis ne peuvent gérer que les commentaires et réponses. Jager te dit ce qu'il a pu et n'a pas pu retirer.")),
    (t("What does the AI see?","Que voit l'IA ?"),t("Only what is needed for the job: the text of a comment and the draft context. It goes to the model provider you chose with your own key. Jager keeps nothing on our side.","Seulement ce qui est nécessaire : le texte d'un commentaire et le contexte du brouillon. Cela part chez le fournisseur de modèle que tu as choisi, avec ta propre clé. Jager ne garde rien de notre côté.")),
    (t("Who sees my data?","Qui voit mes données ?"),t("Your server, Zernio and the AI provider you choose. Jager itself collects nothing. Read the code to check.","Ton serveur, Zernio et le fournisseur d'IA que tu choisis. Jager lui-même ne collecte rien. Lis le code pour vérifier.")),
    (t("Which languages does Jager speak?","Quelles langues parle Jager ?"),t("English and French today, on the site and in the chat. The language menu lists 30 more, including Hebrew and Arabic. Translations are welcome as pull requests.","Anglais et français aujourd'hui, sur le site et dans le chat. Le menu des langues en liste 30 autres, dont l'hébreu et l'arabe. Les traductions sont bienvenues en pull request.")),
    (t("Can I contribute?","Puis-je contribuer ?"),t("Please do. Open an issue or a pull request on GitHub.","Volontiers. Ouvre une issue ou une pull request sur GitHub.")),
    (t("Is this affiliated with Jägermeister, Zernio, WhatsApp or Telegram?","Est-ce affilié à Jägermeister, Zernio, WhatsApp ou Telegram ?"),t("No to all of them. Jägermeister is just a pun, and a very on-brand one.","Non, à aucun. Jägermeister n'est qu'un jeu de mots, et très dans le ton."))]
